CREATE TABLE facilitator_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL UNIQUE REFERENCES users(id), staff_code VARCHAR(40) UNIQUE, state_id UUID REFERENCES states(id), lga_id UUID REFERENCES lgas(id), supervisor_user_id UUID REFERENCES users(id), status VARCHAR(20) NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','SUSPENDED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX facilitator_state_idx ON facilitator_profiles(state_id); CREATE INDEX facilitator_lga_idx ON facilitator_profiles(lga_id);
